export default function collectAirtableRows({previousState,records,offset}) {
 const state=previousState?{records:[...previousState.records],cursors:[...previousState.cursors]}:{records:[],cursors:[]};
 if(previousState){if(!Array.isArray(records))throw new Error('Airtable returned no record array.');for(const record of records){if(!record||typeof record.id!=='string'||!record.id||!record.fields||typeof record.fields!=='object'||Array.isArray(record.fields))throw new Error('Invalid Airtable record.');state.records.push(record);}if(offset!==undefined&&offset!==null&&(typeof offset!=='string'||!offset))throw new Error('Invalid Airtable cursor.');if(offset){if(state.cursors.includes(offset))throw new Error('Airtable repeated its pagination cursor.');state.cursors.push(offset);}}
 const more=!previousState||!!offset;return {state,offset:more?(offset??null):null,more,hasRecords:state.records.length>0};
}

