export default function planSheetSync({records,values,range,majorDimension}) {
 if(!Array.isArray(records)||!records.length)throw new Error('At least one selected Airtable record is required.');
 if(majorDimension!=='ROWS'||!Array.isArray(values)||!Array.isArray(values[0]))throw new Error('A sheet header row is required.');
 const headers=values[0];if(!headers.length||headers.length>5||headers.some(h=>typeof h!=='string'||!h)||new Set(headers).size!==headers.length||!headers.includes('Email'))throw new Error('The A1:E1 headers must be unique text field names including Email, with no gaps.');
 if(typeof range!=='string'||range.lastIndexOf('!')<1||range.slice(range.lastIndexOf('!')+1)!=='A1:E1000')throw new Error('The sheet response must identify the requested A1:E1000 lookup window.');
 const prefix=range.slice(0,range.lastIndexOf('!')+1),keyIndex=headers.indexOf('Email'),existing=new Map(),sourceKeys=new Set(),data=[],newRows=[],matched=[],unchanged=[];
 if(values.length>1000)throw new Error('The sheet response exceeds the configured lookup window.');
 for(let i=1;i<values.length;i++){const row=values[i];if(!Array.isArray(row)||row.length>5)throw new Error('Invalid sheet row.');const key=row[keyIndex];if(key!==null&&key!==undefined&&key!==''){if(typeof key!=='string')throw new Error('Existing Email keys must be text.');if(existing.has(key))throw new Error('Duplicate Email keys exist in the target lookup window.');existing.set(key,i+1);}}
 for(const record of records){const fields=record?.fields,key=fields?.Email;if(!record?.id||!fields||typeof fields!=='object'||Array.isArray(fields)||typeof key!=='string'||!key.trim())throw new Error('Every selected record needs a nonempty text Email key.');if(sourceKeys.has(key))throw new Error('Duplicate Email keys exist in the source batch.');sourceKeys.add(key);
  for(const h of headers){const v=fields[h];if(v!==undefined&&v!==null&&!['string','number','boolean'].includes(typeof v))throw new Error('Mapped Airtable cells must be text,numbers,booleans or null.');if(typeof v==='number'&&!Number.isFinite(v))throw new Error('Mapped numbers must be finite.');}
  const rowNumber=existing.get(key);if(rowNumber){const before=data.length;headers.forEach((h,j)=>{if(h!=='Email'&&fields[h]!==undefined&&fields[h]!==null)data.push({range:prefix+String.fromCharCode(65+j)+rowNumber,majorDimension:'ROWS',values:[[fields[h]]]});});(data.length>before?matched:unchanged).push({recordId:record.id,email:key,row:rowNumber});}
  else newRows.push({recordId:record.id,email:key,values:headers.map(h=>fields[h]===undefined||fields[h]===null?'':String(fields[h]))});
 }
 return {data:data.length?data:[{range:prefix+'A1',values:[['UNUSED']],majorDimension:'ROWS'}],newRows,hasUpdates:data.length>0,plan:{matched,unchanged,count:records.length,ranges:data.map(d=>d.range),cells:data.length,newRows,tableRange:range,width:headers.length}};
}

