export default function collectContactAppends({plan,previousState,updatedRange,updatedRows,updatedCells}) {
 const state=previousState?{index:previousState.index,inserted:[...previousState.inserted]}:{index:0,inserted:[]};
 if(previousState){const expected=plan.newRows[state.index],prefix=plan.tableRange.slice(0,plan.tableRange.lastIndexOf('!')+1),suffix=typeof updatedRange==='string'&&updatedRange.startsWith(prefix)?updatedRange.slice(prefix.length):'',match=suffix.match(/^A([0-9]+)(?::([A-E])([0-9]+))?$/);if(updatedRows!==1||updatedCells!==plan.width||!match||match[1]!==(match[3]??match[1])||(match[2]??'A')!==String.fromCharCode(64+plan.width))throw new Error('Append receipt does not confirm the new contact row. Inspect the sheet before retrying.');state.inserted.push({recordId:expected.recordId,email:expected.email,range:updatedRange,row:Number(match[1])});state.index++;}
 const next=plan.newRows[state.index];return {state,more:!!next,values:next?[next.values]:[]};
}

