export default function confirmSheetSync({plan,inserted,totalUpdatedRows,totalUpdatedCells,responses}) {
 if(inserted.length!==plan.newRows.length)throw new Error('All new contact appends must complete before updating existing rows.');
 if(plan.cells){if(totalUpdatedRows!==plan.matched.length||totalUpdatedCells!==plan.cells||!Array.isArray(responses)||responses.length!==plan.cells)throw new Error('The update did not confirm every planned cell. Inspect the sheet before retrying.');
  const canonical=r=>String(r).replace(/([A-Z]+\d+):\1$/,'$1');for(let i=0;i<responses.length;i++){const r=responses[i];if(r.updatedRows!==1||r.updatedCells!==1||canonical(r.updatedRange)!==canonical(plan.ranges[i]))throw new Error('A cell write receipt is incomplete. Inspect the sheet before retrying.');}}
 return {rowsUpdated:plan.matched.length,rowsInserted:inserted.length,rowsUnchanged:plan.unchanged.length,totalRowsProcessed:plan.count,updated:plan.matched,inserted};
}
